fn sum(take n: Int, take acc: Int) -> Int {
    if n == 0 { acc } else { sum(n - 1, acc + n) }
}
fn main() -> Int { sum(1000, 0) }

fn f(take n: Int) -> Int { n + 1 }
fn g(take n: Int) -> Int { f(n) + f(n) }
fn main() -> Int { g(3) + g(4) + g(5) }

// indirect-calls — a hot loop calling through a first-class function VALUE
// (ADR-0008 Tier 1), the indirect-call sibling of the `function-calls`
// workload (which measures only direct calls). `step` is a
// `fn(take Int, take Int) -> Int` value: `main` passes the top-level `add` by
// name (the only way to obtain a function value in Tier 1), and `fold` invokes
// it through the indirect-call path once per iteration. The equivalent C peer
// (`benchmarks/runtime/programs/c/indirect-calls.c`) runs the identical loop
// calling through a function pointer, so the comparison isolates the indirect
// dispatch itself: same arithmetic, same iteration count, same exit.
fn add(take a: Int, take b: Int) -> Int {
    a + b
}

// Fold `step` over `reps` iterations, adding 1 each time. Every `step(acc, 1)`
// is an indirect call through the function value — the operation being measured.
fn fold(take reps: Int, take step: fn(take Int, take Int) -> Int) -> Int {
    var acc = 0;
    var i = 0;
    while i < reps {
        acc = step(acc, 1);
        i = i + 1;
    }
    acc
}

fn main() -> Int {
    // 2_000_000 indirect calls through `add`, each contributing 1, so
    // acc = 2_000_000. Observable exit byte = 2_000_000 & 0xff = 128.
    fold(2000000, add)
}

fn fib(take n: Int) -> Int {
    if n < 2 { n } else { fib(n - 1) + fib(n - 2) }
}
fn main() -> Int { fib(20) }

fn lookup(take table: [Int; 8], take i: Usize) -> Int {
    table[i]
}

fn scan(take table: [Int; 8]) -> Int {
    var total = 0;
    for x in table {
        total = total + x;
    }
    total
}

fn probe(take table: [Int; 8]) -> Int {
    lookup(table, 0) + lookup(table, 3) + lookup(table, 7)
}

fn main() -> Int {
    let table = [3, 1, 4, 1, 5, 9, 2, 6];
    var total = 0;
    var round = 0;
    while round < 200 {
        total = total + scan(table) + probe(table);
        round = round + 1;
    }
    total
}

fn line() -> Str {
    "GET /users/42 HTTP/1.1 200 1532"
}

fn count_byte(in text: Str, take target: Int) -> Int {
    var found = 0;
    var index = 0;
    while index < std::str::len(text) {
        if std::str::byte_at(text, index) == target {
            found = found + 1;
        }
        index = index + 1;
    }
    found
}

fn count_digits(in text: Str) -> Int {
    var found = 0;
    var index = 0;
    while index < std::str::len(text) {
        let byte = std::str::byte_at(text, index);
        if byte >= 48 && byte <= 57 {
            found = found + 1;
        }
        index = index + 1;
    }
    found
}

fn method_is_get(in text: Str) -> Int {
    if std::str::slice(text, 0, 3) == "GET" {
        1
    } else {
        0
    }
}

fn version_ok(in text: Str) -> Int {
    if std::str::slice(text, 14, 22) == "HTTP/1.1" {
        1
    } else {
        0
    }
}

fn score(in text: Str) -> Int {
    count_byte(text, 32)
        + count_byte(text, 47)
        + count_digits(text)
        + method_is_get(text)
        + version_ok(text)
}

fn main() -> Int {
    var total = 0;
    var round = 0;
    while round < 200 {
        total = total + score(line());
        round = round + 1;
    }
    total
}

// allocation — heap allocation and deallocation throughput over the ADR-0009
// allocator core (owned `String` + growable `Array[Int]`).
//
// Each round allocates two real heap buffers and frees them at scope end:
//   * a growable `Array[Int]` filled 0..COUNT by repeated `push` (which grows
//     the backing buffer by doubling — alloc-new + copy + free-old), then
//     scanned with `len`/`get`; the sum of 0..COUNT is COUNT*(COUNT-1)/2;
//   * an owned `String` built to COUNT bytes by repeated `push_byte` (the same
//     growth path over the byte buffer), then measured with `len`.
// A round's contribution is deterministic — array sum + string length — and the
// loop runs it ROUNDS times so the workload really exercises allocate/grow/free
// throughput (a leak would OOM; a double-free would abort). The observable
// result is one round's contribution (reassigned, not accumulated, so the exit
// stays a small documented byte): for COUNT = 16 the array sums to 120 and the
// string is 16 bytes, so `main` returns 136 (exit byte 136).

fn array_sum(take count: Int) -> Int {
    var xs = std::array::empty();
    var i = 0;
    while i < count {
        std::array::push(xs, i);
        i = i + 1;
    }
    var total = 0;
    var j = 0;
    while j < std::array::len(xs) {
        total = total + std::array::get(xs, j);
        j = j + 1;
    }
    total
}

fn string_len(take count: Int) -> Int {
    var s = std::string::empty();
    var i = 0;
    while i < count {
        std::string::push_byte(s, 65);
        i = i + 1;
    }
    std::string::len(s)
}

fn round(take count: Int) -> Int {
    array_sum(count) + string_len(count)
}

fn main() -> Int {
    var result = 0;
    var r = 0;
    while r < 2000 {
        result = round(16);
        r = r + 1;
    }
    result
}

// map-lookup — keyed insert/lookup/churn throughput over the ADR-0011 hash
// map (`Map[Int, Int]`, the `tuo_rt_map_*` open-addressing table behind the
// three-word header).
//
// One round: insert COUNT entries (key i → value 3·i, growing the table by
// doubling through several thresholds), look every key back up summing the
// values modulo 1000, then remove the first half (the order-preserving
// removal path) and read the surviving entry count. A round's contribution is
// deterministic: for COUNT = 1000 the lookup sum is 3·999·1000/2 = 1_498_500,
// i.e. 500 after the running modulo, and 500 entries survive — 1000 total.
// The loop repeats the round so the workload really exercises hash, probe,
// growth, and removal throughput (a leak would OOM; a double-free would
// abort); the observable result is one round's contribution (reassigned, not
// accumulated): 1000, exit byte 1000 & 0xff = 232.

fn round(take count: Int) -> Int {
    var m = std::map::empty();
    var i = 0;
    while i < count {
        let _ = std::map::insert(m, i, i * 3);
        i = i + 1;
    }
    var hits = 0;
    var j = 0;
    while j < count {
        let value = match std::map::get(m, j) {
            Some { value } => value,
            None => 0,
        };
        hits = (hits + value) % 1000;
        j = j + 1;
    }
    var k = 0;
    while k < count / 2 {
        let _ = std::map::remove(m, k);
        k = k + 1;
    }
    hits + std::map::len(m)
}

fn main() -> Int {
    var result = 0;
    var r = 0;
    while r < 50 {
        result = round(1000);
        r = r + 1;
    }
    result
}

// The file-io workload (ADR-0013): effect-crossing throughput over the OS
// boundary. Each round opens a scratch file for write, writes 15 sixteen-byte
// chunks (240 bytes), closes it, reopens it for read, reads it back
// byte-at-a-time (240 crossings of the read_byte seam), closes it, and
// removes it — so every ADR-0013 file primitive and the ADR-0006 descriptor
// seam are on the hot path. The C peer performs the identical sequence with
// open/write/read/close/unlink.
//
// round(15) returns the byte count read back, 240; main runs 200 rounds and
// returns the last round's count. Observable exit byte: 240 & 0xff = 240.

fn round(take chunks: Int) -> Int {
    let path = "file-io-bench.tmp";
    let fd = std::rt::open(path, 1);
    if fd < 0 {
        return 0 - 1;
    }
    var i = 0;
    while i < chunks {
        std::rt::write(fd, "0123456789abcdef");
        i = i + 1;
    }
    std::rt::close(fd);
    let rfd = std::rt::open(path, 0);
    if rfd < 0 {
        return 0 - 2;
    }
    var count = 0;
    var done = false;
    while !done {
        let b = std::rt::read_byte(rfd);
        if b < 0 {
            done = true;
        } else {
            count = count + 1;
        }
    }
    std::rt::close(rfd);
    std::rt::remove_file(path);
    count
}

fn main() -> Int {
    var result = 0;
    var r = 0;
    while r < 200 {
        result = round(15);
        r = r + 1;
    }
    result
}

// The networking workload (ADR-0014): a basic socket round-trip. Each round
// creates a listening socket on an ephemeral loopback port, connects to it
// (TCP's backlog completes the handshake before accept runs), accepts, sends
// 8 sixteen-byte chunks (128 bytes) from the client, reads them back on the
// server byte-at-a-time (128 crossings of the read_byte seam), and closes
// all three descriptors — so every ADR-0014 socket primitive and the
// ADR-0006 descriptor seam are on the hot path. The C and Go peers perform
// the identical sequence.
//
// round(8) returns the byte count received, 128; main runs 100 rounds and
// returns the last round's count. Observable exit byte: 128 & 0xff = 128.

fn round(take chunks: Int) -> Int {
    let listener = std::rt::listen(0);
    if listener < 0 {
        return 0 - 1;
    }
    let port = std::rt::bound_port(listener);
    if port <= 0 {
        return 0 - 2;
    }
    let client = std::rt::connect("127.0.0.1", port);
    if client < 0 {
        return 0 - 3;
    }
    let server = std::rt::accept(listener);
    if server < 0 {
        return 0 - 4;
    }
    var i = 0;
    while i < chunks {
        std::rt::write(client, "0123456789abcdef");
        i = i + 1;
    }
    var count = 0;
    while count < chunks * 16 {
        let b = std::rt::read_byte(server);
        if b < 0 {
            return 0 - 5;
        }
        count = count + 1;
    }
    std::rt::close(client);
    std::rt::close(server);
    std::rt::close(listener);
    count
}

fn main() -> Int {
    var result = 0;
    var r = 0;
    while r < 100 {
        result = round(8);
        r = r + 1;
    }
    result
}

// The channels workload (ADR-0015): synchronization-crossing throughput over
// the channel primitives. One channel is created up front (handles are
// process-lived); each round sends 500 values through it and receives all
// 500 back, so every iteration crosses the runtime's locked FIFO twice —
// single-threaded on purpose, so the number isolates the crossing cost
// itself (the parallel lab category already measures threading). The C peer
// makes the identical locked crossings through a mutex-and-condvar FIFO; the
// Go peer uses its native buffered channel — the direct Go-parity
// comparison.
//
// round(ch, 500) returns the count received, 500; main runs 200 rounds and
// returns the last round's count. Observable exit byte: 500 & 0xff = 244.

fn round(take ch: Int, take n: Int) -> Int {
    var i = 0;
    while i < n {
        if std::rt::chan_send(ch, i) != 0 {
            return 0 - 1;
        }
        i = i + 1;
    }
    var count = 0;
    while count < n {
        if std::rt::chan_recv(ch) < 0 {
            return 0 - 2;
        }
        count = count + 1;
    }
    count
}

fn main() -> Int {
    let ch = std::rt::chan_new();
    if ch < 0 {
        return 1;
    }
    var result = 0;
    var r = 0;
    while r < 200 {
        result = round(ch, 500);
        r = r + 1;
    }
    result
}

// The json-parse workload (ADR-0016): JSON decoding throughput. Each round
// parses a fixed 149-byte document with a self-contained recursive-descent
// parser over the ADR-0016 data increment (an `Array[Int]`/`Array[Float]`
// kind/number arena — the lab's workloads are single-file by design;
// `std::json` itself is pinned natively by the stdlib suite) and folds a
// structural checksum: 3 × the node count plus the truncated sum of every
// number. The C peer makes the identical walk with `strtod`; the Go peer is
// the parity target itself — `encoding/json` unmarshalling into `any` and
// walking the result to the same checksum.
//
// The document holds 21 nodes and its numbers sum to 247.5, so a round's
// checksum is (21 * 3 + 247) % 256 = 54; main runs 200 rounds and returns
// the last round's checksum (reassigned, not accumulated). Exit byte: 54.

fn doc() -> Str {
    "{\"id\":42,\"name\":\"tuonelang\",\"tags\":[\"fast\",\"safe\",\"native\"],\"metrics\":{\"stars\":128,\"forks\":32,\"score\":9.5},\"active\":true,\"refs\":[1,2,3,4,5,6,7,8]}"
}

fn is_digit(take b: Int) -> Bool {
    b >= 48 && b <= 57
}

fn skip_ws(in s: Str, take pos: Int) -> Int {
    var p = pos;
    while p < std::str::len(s) && std::str::byte_at(s, p) == 32 {
        p = p + 1;
    }
    p
}

// Scan past a string token (the workload document carries no escapes).
fn string_end(in s: Str, take pos: Int) -> Int {
    var p = pos + 1;
    while p < std::str::len(s) && std::str::byte_at(s, p) != 34 {
        p = p + 1;
    }
    p + 1
}

fn number_end(in s: Str, take pos: Int) -> Int {
    var p = pos;
    let n = std::str::len(s);
    if p < n && std::str::byte_at(s, p) == 45 {
        p = p + 1;
    }
    while p < n && is_digit(std::str::byte_at(s, p)) {
        p = p + 1;
    }
    if p < n && std::str::byte_at(s, p) == 46 {
        p = p + 1;
        while p < n && is_digit(std::str::byte_at(s, p)) {
            p = p + 1;
        }
    }
    p
}

fn number_value(in s: Str, take a: Int, take b: Int) -> Float {
    var p = a;
    var negative = false;
    if std::str::byte_at(s, p) == 45 {
        negative = true;
        p = p + 1;
    }
    var value = 0.0;
    while p < b && is_digit(std::str::byte_at(s, p)) {
        value = value * 10.0 + ((std::str::byte_at(s, p) - 48) as Float);
        p = p + 1;
    }
    if p < b && std::str::byte_at(s, p) == 46 {
        p = p + 1;
        var place = 0.1;
        while p < b && is_digit(std::str::byte_at(s, p)) {
            value = value + ((std::str::byte_at(s, p) - 48) as Float) * place;
            place = place / 10.0;
            p = p + 1;
        }
    }
    if negative {
        0.0 - value
    } else {
        value
    }
}

// Parse one value: record its kind (0 scalar, 1 number) and number value,
// returning the position after it (the fixed document is valid, so no error
// path is needed — a mis-parse would derail the checksum and fail the run).
fn parse_value(mut kinds: Array[Int], mut nums: Array[Float], in s: Str, take pos: Int) -> Int {
    let p = skip_ws(s, pos);
    let b = std::str::byte_at(s, p);
    if b == 110 || b == 116 {
        std::array::push(kinds, 0);
        std::array::push(nums, 0.0);
        p + 4
    } else if b == 102 {
        std::array::push(kinds, 0);
        std::array::push(nums, 0.0);
        p + 5
    } else if b == 34 {
        std::array::push(kinds, 0);
        std::array::push(nums, 0.0);
        string_end(s, p)
    } else if b == 91 {
        std::array::push(kinds, 0);
        std::array::push(nums, 0.0);
        parse_items(kinds, nums, s, p + 1, 93)
    } else if b == 123 {
        std::array::push(kinds, 0);
        std::array::push(nums, 0.0);
        parse_items(kinds, nums, s, p + 1, 125)
    } else {
        let e = number_end(s, p);
        std::array::push(kinds, 1);
        std::array::push(nums, number_value(s, p, e));
        e
    }
}

// Parse a container's items up to the closer: array elements, or an
// object's `"key": value` members (the key string is skipped, not a node).
fn parse_items(mut kinds: Array[Int], mut nums: Array[Float], in s: Str, take pos: Int, take closer: Int) -> Int {
    var p = skip_ws(s, pos);
    if std::str::byte_at(s, p) == closer {
        return p + 1;
    }
    var done = false;
    while !done {
        if closer == 125 {
            p = skip_ws(s, p);
            p = string_end(s, p);
            p = skip_ws(s, p);
            p = p + 1;
        }
        p = parse_value(kinds, nums, s, p);
        p = skip_ws(s, p);
        let c = std::str::byte_at(s, p);
        p = p + 1;
        if c == closer {
            done = true;
        }
    }
    p
}

fn round() -> Int {
    var kinds = std::array::empty();
    var nums = std::array::empty();
    let text = doc();
    parse_value(kinds, nums, text, 0);
    let nodes = std::array::len(kinds);
    var sum = 0.0;
    var i = 0;
    while i < std::array::len(nums) {
        sum = sum + std::array::get(nums, i);
        i = i + 1;
    }
    (nodes * 3 + (sum as Int)) % 256
}

fn main() -> Int {
    var result = 0;
    var r = 0;
    while r < 200 {
        result = round();
        r = r + 1;
    }
    result
}

// The sha256-hash workload (ADR-0019): cryptographic hashing throughput. Each
// round computes the SHA-256 of a fixed 64-byte message — exactly one
// compression block after padding, so the measurement is one block's worth of
// the compression function and nothing else.
//
// The lab's workloads are single-file by design, so the compression function
// is inlined here rather than imported; `std::crypto` itself is pinned
// natively by the stdlib suite and cross-checked against the toolchain's Rust
// SHA-256 in `tuo-cli/tests/crypto_cross_check.rs`. The C peer makes the
// identical computation with `uint32_t` and `>>`/`<<`/`^`; the Go peer is the
// parity target itself — the standard library's `crypto/sha256`.
//
// Every hash word is combined with `add32` (masked addition), never a bare
// `+`: tuonelang's `+` traps on overflow, which is correct for arithmetic and
// wrong for a checksum defined over modular arithmetic. That distinction is
// the reason ADR-0019 Stage B's `std::bits` exists.
//
// The message is 64 ASCII '0'..'9' bytes, whose SHA-256 is
// 9674d9e0...; its first byte, 0x96 = 150, is the value main returns. 200
// rounds, the last round's byte returned (reassigned, not accumulated).
// Exit byte: 150.

fn mask32() -> Int {
    4294967295
}

fn add32(take a: Int, take b: Int) -> Int {
    ((a & 4294967295) + (b & 4294967295)) & 4294967295
}

fn rotr32(take value: Int, take n: Int) -> Int {
    let masked = value & 4294967295;
    if n <= 0 {
        return masked;
    }
    let amount = n % 32;
    if amount == 0 {
        return masked;
    }
    ((masked >> amount) | (masked << (32 - amount))) & 4294967295
}

fn shr32(take value: Int, take n: Int) -> Int {
    let masked = value & 4294967295;
    if n <= 0 {
        return masked;
    }
    if n >= 32 {
        return 0;
    }
    (masked >> n) & 4294967295
}

fn be32(take b0: Int, take b1: Int, take b2: Int, take b3: Int) -> Int {
    ((b0 & 255) << 24) | ((b1 & 255) << 16) | ((b2 & 255) << 8) | (b3 & 255)
}

