    std::array::push(k, 1537002063); std::array::push(k, 1747873779);
    std::array::push(k, 1955562222); std::array::push(k, 2024104815);
    std::array::push(k, 2227730452); std::array::push(k, 2361852424);
    std::array::push(k, 2428436474); std::array::push(k, 2756734187);
    std::array::push(k, 3204031479); std::array::push(k, 3329325298);
    k
}

// The 64-byte message: ASCII digits cycling 0..9.
fn message() -> Array[Int] {
    var m = std::array::empty();
    var i = 0;
    while i < 64 {
        std::array::push(m, 48 + (i % 10));
        i = i + 1;
    }
    m
}

// A 64-byte input pads to exactly two blocks: the message, then 0x80, zeros,
// and the 64-bit big-endian bit length (512 = 0x200).
fn padded() -> Array[Int] {
    var m = message();
    std::array::push(m, 128);
    while (std::array::len(m) % 64) != 56 {
        std::array::push(m, 0);
    }
    var i = 0;
    while i < 6 {
        std::array::push(m, 0);
        i = i + 1;
    }
    std::array::push(m, 2);
    std::array::push(m, 0);
    m
}

fn first_digest_byte(in msg: Array[Int], in k: Array[Int]) -> Int {
    var h0 = 1779033703;
    var h1 = 3144134277;
    var h2 = 1013904242;
    var h3 = 2773480762;
    var h4 = 1359893119;
    var h5 = 2600822924;
    var h6 = 528734635;
    var h7 = 1541459225;

    let blocks = std::array::len(msg) / 64;
    var block = 0;
    while block < blocks {
        let base = block * 64;
        var w = std::array::empty();
        var t = 0;
        while t < 16 {
            let at = base + (t * 4);
            std::array::push(w, be32(
                std::array::get(msg, at),
                std::array::get(msg, at + 1),
                std::array::get(msg, at + 2),
                std::array::get(msg, at + 3)
            ));
            t = t + 1;
        }
        t = 16;
        while t < 64 {
            let w15 = std::array::get(w, t - 15);
            let w2 = std::array::get(w, t - 2);
            let s0 = rotr32(w15, 7) ^ rotr32(w15, 18) ^ shr32(w15, 3);
            let s1 = rotr32(w2, 17) ^ rotr32(w2, 19) ^ shr32(w2, 10);
            std::array::push(w, add32(
                add32(std::array::get(w, t - 16), s0),
                add32(std::array::get(w, t - 7), s1)
            ));
            t = t + 1;
        }

        var a = h0;
        var b = h1;
        var c = h2;
        var d = h3;
        var e = h4;
        var f = h5;
        var g = h6;
        var h = h7;

        var r = 0;
        while r < 64 {
            let big1 = rotr32(e, 6) ^ rotr32(e, 11) ^ rotr32(e, 25);
            let choose = (e & f) ^ ((~e) & g & 4294967295);
            let temp1 = add32(
                add32(h, big1),
                add32(add32(choose, std::array::get(k, r)), std::array::get(w, r))
            );
            let big0 = rotr32(a, 2) ^ rotr32(a, 13) ^ rotr32(a, 22);
            let major = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = add32(big0, major);
            h = g;
            g = f;
            f = e;
            e = add32(d, temp1);
            d = c;
            c = b;
            b = a;
            a = add32(temp1, temp2);
            r = r + 1;
        }

        h0 = add32(h0, a);
        h1 = add32(h1, b);
        h2 = add32(h2, c);
        h3 = add32(h3, d);
        h4 = add32(h4, e);
        h5 = add32(h5, f);
        h6 = add32(h6, g);
        h7 = add32(h7, h);
        block = block + 1;
    }

    (h0 >> 24) & 255
}

fn main() -> Int {
    let k = round_constants();
    var byte = 0;
    var round = 0;
    while round < 200 {
        byte = first_digest_byte(padded(), k);
        round = round + 1;
    }
    byte
}

// The wire-decode workload (ADR-0019): binary protocol framing throughput.
// Each round walks a fixed 256-byte buffer as a sequence of length-prefixed
// messages — the shape every binary wire protocol uses, and the concrete case
// ADR-0019 was opened for: a PostgreSQL protocol message is a type byte plus a
// big-endian Int32 length.
//
// Per message the round reads a 4-byte big-endian length, a 2-byte big-endian
// type, folds the payload bytes, and re-encodes the length back to bytes to
// check the round-trip — so both directions of the byte-order conversion are
// measured, not just decoding. The C peer makes the identical shifts and masks
// on `uint32_t`; the Go peer uses `encoding/binary`'s `BigEndian.Uint32`/
// `PutUint32` (the parity target).
//
// This is the workload that could not be written before ADR-0019 Stage A. The
// arithmetic form `b0*16777216 + b1*65536 + b2*256 + b3` computes the same
// value for well-formed input, but masking (`x & 0xFF`), field extraction
// (`x >> 24`), and the type/flag tests below have no arithmetic spelling at
// all — the operation being measured simply had no expression.
//
// The buffer holds 16 messages of 16 bytes each (a 4-byte length, a 2-byte
// type, and a 10-byte payload). The checksum folds every decoded field mod
// 256; main runs 200 rounds and returns the last round's checksum
// (reassigned, not accumulated). Exit byte: 120.

fn be32(take b0: Int, take b1: Int, take b2: Int, take b3: Int) -> Int {
    ((b0 & 255) << 24) | ((b1 & 255) << 16) | ((b2 & 255) << 8) | (b3 & 255)
}

fn be16(take b0: Int, take b1: Int) -> Int {
    ((b0 & 255) << 8) | (b1 & 255)
}

fn byte_of_be32(take value: Int, take index: Int) -> Int {
    ((value & 4294967295) >> ((3 - index) * 8)) & 255
}

// A 256-byte buffer: 16 frames of 16 bytes. Each frame is
// [0, 0, 0, 16] (the big-endian length), [0, type], then 10 payload bytes.
fn buffer() -> Array[Int] {
    var b = std::array::empty();
    var frame = 0;
    while frame < 16 {
        std::array::push(b, 0);
        std::array::push(b, 0);
        std::array::push(b, 0);
        std::array::push(b, 16);
        std::array::push(b, 0);
        std::array::push(b, 64 + frame);
        var i = 0;
        while i < 10 {
            std::array::push(b, (frame * 7 + i) & 255);
            i = i + 1;
        }
        frame = frame + 1;
    }
    b
}

fn decode(in buf: Array[Int]) -> Int {
    var checksum = 0;
    var pos = 0;
    let n = std::array::len(buf);
    while pos + 6 <= n {
        let length = be32(
            std::array::get(buf, pos),
            std::array::get(buf, pos + 1),
            std::array::get(buf, pos + 2),
            std::array::get(buf, pos + 3)
        );
        let kind = be16(std::array::get(buf, pos + 4), std::array::get(buf, pos + 5));

        // The round-trip: re-encoding the length must reproduce the bytes
        // that were read, which is what makes this measure both directions.
        var rebuilt = 0;
        var j = 0;
        while j < 4 {
            if byte_of_be32(length, j) == std::array::get(buf, pos + j) {
                rebuilt = rebuilt + 1;
            }
            j = j + 1;
        }
        checksum = (checksum + rebuilt) & 255;

        // Fold the payload, and the decoded header fields.
        checksum = (checksum + (length & 255) + (kind & 255)) & 255;
        var p = pos + 6;
        while p < pos + length && p < n {
            checksum = (checksum ^ std::array::get(buf, p)) & 255;
            p = p + 1;
        }
        if length <= 0 {
            return checksum;
        }
        pos = pos + length;
    }
    checksum
}

fn main() -> Int {
    let buf = buffer();
    var checksum = 0;
    var round = 0;
    while round < 200 {
        checksum = decode(buf);
        round = round + 1;
    }
    checksum
}

// The udp-echo workload (ADR-0017): a datagram round-trip. Each round binds
// two UDP sockets on ephemeral loopback ports, sends 8 sixteen-byte
// datagrams from the client to the server, and for each one receives it,
// reads all 16 bytes back through udp_byte_at, and echoes a reply to the
// port udp_peer_port reports — which the client then receives. So every
// ADR-0017 UDP primitive is on the hot path, and unlike the TCP `networking`
// workload the measurement is of *message* delivery, not stream bytes. The C
// and Go peers perform the identical sequence.
//
// round(8) returns the byte count read back, 8 × 16 = 128; main runs 100
// rounds and returns the last round's count. Observable exit byte: 128.

fn round(take datagrams: Int) -> Int {
    let server = std::rt::udp_bind(0);
    if server < 0 {
        return 0 - 1;
    }
    let sport = std::rt::bound_port(server);
    if sport <= 0 {
        return 0 - 2;
    }
    let client = std::rt::udp_bind(0);
    if client < 0 {
        return 0 - 3;
    }
    var count = 0;
    var i = 0;
    while i < datagrams {
        if std::rt::udp_send(client, "127.0.0.1", sport, "0123456789abcdef") != 16 {
            return 0 - 4;
        }
        if std::rt::udp_recv(server, 1000) != 16 {
            return 0 - 5;
        }
        var b = 0;
        while b < 16 {
            if std::rt::udp_byte_at(server, b) < 0 {
                return 0 - 6;
            }
            count = count + 1;
            b = b + 1;
        }
        let from = std::rt::udp_peer_port(server);
        if from <= 0 {
            return 0 - 7;
        }
        if std::rt::udp_send(server, "127.0.0.1", from, "ok") != 2 {
            return 0 - 8;
        }
        if std::rt::udp_recv(client, 1000) != 2 {
            return 0 - 9;
        }
        i = i + 1;
    }
    std::rt::close(client);
    std::rt::close(server);
    count
}

fn main() -> Int {
    var result = 0;
    var r = 0;
    while r < 100 {
        result = round(8);
        r = r + 1;
    }
    result
}

// The connect-timeout workload (ADR-0017): the cost of a *bounded failure*.
// Each round attempts connect_timeout to a loopback port nothing listens on
// and requires the attempt to come back — as a refusal (the usual loopback
// behavior, where the kernel answers RST immediately) or as the -3 timeout —
// rather than hanging. This is the workload that could not be written before
// ADR-0017: with only the blocking `connect`, a peer that never answers has
// no bounded outcome at all. The C peer uses non-blocking connect + poll and
// the Go peer uses net.DialTimeout, both with the identical deadline.
//
// A port is chosen by binding a listener, reading its ephemeral port, and
// closing it — so the port is real and almost certainly unused. round()
// returns 1 per bounded outcome; main runs 200 rounds and returns the count,
// so the observable exit byte is 200.

fn dead_port() -> Int {
    let probe = std::rt::listen(0);
    if probe < 0 {
        return 0 - 1;
    }
    let port = std::rt::bound_port(probe);
    std::rt::close(probe);
    port
}

fn round(take port: Int, take ms: Int) -> Int {
    let fd = std::rt::connect_timeout("127.0.0.1", port, ms);
    if fd >= 0 {
        // Something actually accepted: not the bounded-failure path.
        std::rt::close(fd);
        return 0;
    }
    // A refusal (-1) or the -3 timeout both mean the attempt came back.
    1
}

fn main() -> Int {
    let port = dead_port();
    if port <= 0 {
        return 0 - 1;
    }
    var count = 0;
    var r = 0;
    while r < 200 {
        count = count + round(port, 50);
        r = r + 1;
    }
    count
}

workload.peer_source:
// startup — the equivalent-semantics Go peer for the tuonelang `startup`
// workload. A trivial program that starts and exits 0. The Go runtime's
// scheduler/GC startup is part of what is measured — that is exactly the point
// of an AOT-native peer that ships a runtime: the observable is the same (exit
// 0), the startup cost is the language's own.
package main

import "os"

func main() { os.Exit(0) }

static int sum(int n, int acc) {
    return n == 0 ? acc : sum(n - 1, acc + n);
}
int main(void) { return sum(1000, 0); }

// integer-computation — the equivalent-semantics Go peer. Same tail-recursive
// integer reduction as the C peer and the tuonelang program: sum(1..=1000) by
// recursion = 500500; observable exit byte = 500500 & 0xff = 20.
package main

import "os"

func sum(n, acc int32) int32 {
	if n == 0 {
		return acc
	}
	return sum(n-1, acc+n)
}

func main() { os.Exit(int(sum(1000, 0))) }

static int f(int n) { return n + 1; }
static int g(int n) { return f(n) + f(n); }
int main(void) { return g(3) + g(4) + g(5); }

// function-calls — the equivalent-semantics Go peer. Same non-recursive call
// tree as the C peer and the tuonelang program: g(3)+g(4)+g(5) where
// g(n) = f(n)+f(n) and f(n) = n+1, giving 30.
package main

import "os"

func f(n int32) int32 { return n + 1 }
func g(n int32) int32 { return f(n) + f(n) }

func main() { os.Exit(int(g(3) + g(4) + g(5))) }

// indirect-calls — the equivalent-semantics C peer for the tuonelang
// `indirect-calls` workload (ADR-0008 Tier 1). It runs the identical loop,
// calling through a **function pointer** rather than tuonelang's function value:
// the same arithmetic (`acc += add(acc, 1)`-style step), the same 2,000,000
// iterations, and the same observable exit (2_000_000 & 0xff = 128). This is the
// indirect-call sibling of function-calls.c, which calls f/g directly.
static int add(int a, int b) { return a + b; }

static int fold(int reps, int (*step)(int, int)) {
    int acc = 0;
    for (int i = 0; i < reps; i++) {
        acc = step(acc, 1);
    }
    return acc;
}

int main(void) {
    // 2_000_000 indirect calls through the `add` function pointer; acc = 2_000_000,
    // exit byte 2_000_000 & 0xff = 128.
    return fold(2000000, add);
}

// indirect-calls — the equivalent-semantics Go peer for the tuonelang
// `indirect-calls` workload (ADR-0008 Tier 1). It runs the identical loop,
// calling through a **function value** (Go's first-class func, the closest peer
// to tuonelang's non-capturing function value and to C's function pointer): the
// same arithmetic (`acc = step(acc, 1)`), the same 2,000,000 iterations, and the
// same observable exit (2_000_000 & 0xff = 128). The indirect-call sibling of
// function-calls.go, which calls f/g directly.
package main

import "os"

func add(a, b int32) int32 { return a + b }

func fold(reps int32, step func(int32, int32) int32) int32 {
	var acc int32 = 0
	for i := int32(0); i < reps; i++ {
		acc = step(acc, 1)
	}
	return acc
}

func main() {
	// 2_000_000 indirect calls through the `add` function value; acc = 2_000_000,
	// exit byte 2_000_000 & 0xff = 128.
	os.Exit(int(fold(2000000, add)))
}

static int fib(int n) {
    return n < 2 ? n : fib(n - 1) + fib(n - 2);
}
int main(void) { return fib(20); }

// recursion — the equivalent-semantics Go peer. Same naive tree recursion as
// the C peer and the tuonelang program: fib(20) = 6765; observable exit byte =
// 6765 & 0xff = 109.
package main

import "os"

func fib(n int32) int32 {
	if n < 2 {
		return n
	}
	return fib(n-1) + fib(n-2)
}

func main() { os.Exit(int(fib(20))) }

static long long lookup(const long long table[8], long long i) { return table[i]; }

static long long scan(const long long table[8]) {
    long long total = 0;
    for (int k = 0; k < 8; k++) {
        total += table[k];
    }
    return total;
}

static long long probe(const long long table[8]) {
    return lookup(table, 0) + lookup(table, 3) + lookup(table, 7);
}

int main(void) {
    long long table[8] = {3, 1, 4, 1, 5, 9, 2, 6};
    long long total = 0;
    for (long long round = 0; round < 200; round++) {
        total += scan(table) + probe(table);
    }
    return (int)total;
}

// collections — the equivalent-semantics Go peer for the tuonelang
// `collections` workload (ADR-0004 Stage 2's fixed-size array `[Int; 8]`). The
// closest Go peer to a fixed inline array is a value-type `[8]int64` (not a
// heap slice): the same bulk scan and indexed probes, the same 200 rounds. Each
// round scans (3+1+4+1+5+9+2+6 = 31) and probes indices 0,3,7 (3+1+6 = 10), so
// 200 × 41 = 8200; observable exit byte = 8200 & 0xff = 8.
package main

import "os"

func lookup(table [8]int64, i int64) int64 { return table[i] }

func scan(table [8]int64) int64 {
	var total int64 = 0
	for k := 0; k < 8; k++ {
		total += table[k]
	}
	return total
}

func probe(table [8]int64) int64 {
	return lookup(table, 0) + lookup(table, 3) + lookup(table, 7)
}

func main() {
	table := [8]int64{3, 1, 4, 1, 5, 9, 2, 6}
	var total int64 = 0
	for round := 0; round < 200; round++ {
		total += scan(table) + probe(table)
	}
	os.Exit(int(total))
}

static const char line_text[] = "GET /users/42 HTTP/1.1 200 1532";
static const int line_len = (int)(sizeof line_text - 1);

static int count_byte(const char *text, int len, int target) {
    int found = 0;
    for (int i = 0; i < len; i++) {
        if ((unsigned char)text[i] == target) {
            found++;
        }
    }
    return found;
}

static int count_digits(const char *text, int len) {
    int found = 0;
    for (int i = 0; i < len; i++) {
        unsigned char byte = (unsigned char)text[i];
        if (byte >= 48 && byte <= 57) {
            found++;
        }
    }
    return found;
}

static int slice_equals(const char *text, int start, int end, const char *expect) {
    for (int i = start; i < end; i++) {
        if (text[i] != expect[i - start]) {
            return 0;
        }
    }
    return expect[end - start] == '\0';
}

static int score(const char *text, int len) {
    return count_byte(text, len, 32) + count_byte(text, len, 47) +
           count_digits(text, len) + slice_equals(text, 0, 3, "GET") +
           slice_equals(text, 14, 22, "HTTP/1.1");
}

int main(void) {
    int total = 0;
    for (int round = 0; round < 200; round++) {
        total += score(line_text, line_len);
    }
    return total;
}

// string-processing — the equivalent-semantics Go peer for the tuonelang
// `string-processing` workload (ADR-0006's borrowed `Str`). Byte-level scanning
// over a fixed request-log line, done the same way: count spaces (32) and
// slashes (47), count ASCII digits, and compare two fixed slices against "GET"
// and "HTTP/1.1". Go's []byte view of a string is the peer to tuonelang's byte
// slicing over `Str`. Per round: 4 spaces + 3 slashes + 11 digits + 1 + 1 = 20;
// 200 rounds × 20 = 4000; observable exit byte = 4000 & 0xff = 160.
package main

import "os"

var lineText = []byte("GET /users/42 HTTP/1.1 200 1532")

func countByte(text []byte, target byte) int {
	found := 0
	for i := 0; i < len(text); i++ {
		if text[i] == target {
			found++
		}
	}
	return found
}

func countDigits(text []byte) int {
	found := 0
	for i := 0; i < len(text); i++ {
		b := text[i]
		if b >= 48 && b <= 57 {
			found++
		}
	}
	return found
}

func sliceEquals(text []byte, start, end int, expect string) int {
	if end-start != len(expect) {
		return 0
	}
	for i := start; i < end; i++ {
		if text[i] != expect[i-start] {
			return 0
		}
	}
	return 1
}

func score(text []byte) int {
	return countByte(text, 32) + countByte(text, 47) +
		countDigits(text) + sliceEquals(text, 0, 3, "GET") +
		sliceEquals(text, 14, 22, "HTTP/1.1")
}

func main() {
	total := 0
	for round := 0; round < 200; round++ {
		total += score(lineText)
	}
	os.Exit(total)
}

// allocation — the equivalent-semantics C peer for the tuonelang allocation
// workload. Same computation the same way: a growable long-long vector filled
// 0..count by push (doubling growth via realloc), summed; and a growable byte
// buffer filled to `count` bytes the same way, measured by length. Each round's
// buffers are freed at scope end; the round is repeated so the workload really
// exercises malloc/realloc/free throughput. The observable result is one
// round's contribution (reassigned, not accumulated), matching the tuonelang
// program: for count = 16 the vector sums to 120 and the buffer is 16 bytes, so
// main returns 136.

#include <stdlib.h>
#include <string.h>

static long long array_sum(int count) {
    long long *xs = NULL;
    long long len = 0;
    long long cap = 0;
    for (int i = 0; i < count; i++) {
        if (len == cap) {
            cap = cap == 0 ? 1 : cap * 2;
            xs = (long long *)realloc(xs, (size_t)cap * sizeof(long long));
        }
        xs[len++] = i;
    }
    long long total = 0;
    for (long long j = 0; j < len; j++) {
        total += xs[j];
    }
    free(xs);
    return total;
}

static long long string_len(int count) {
    unsigned char *s = NULL;
    long long len = 0;
    long long cap = 0;
    for (int i = 0; i < count; i++) {
        if (len == cap) {
            cap = cap == 0 ? 1 : cap * 2;
            s = (unsigned char *)realloc(s, (size_t)cap);
        }
        s[len++] = 65;
    }
    free(s);
    return len;
}

static long long round_once(int count) {
    return array_sum(count) + string_len(count);
}

int main(void) {
    long long result = 0;
    for (int r = 0; r < 2000; r++) {
        result = round_once(16);
    }
    return (int)result;
}

// allocation — the equivalent-semantics Go peer for the tuonelang allocation
// workload (ADR-0009's owned `String` and growable `Array[Int]`). Same
// computation the same way: a growable int64 vector filled 0..count by push
// with **explicit doubling growth** (mirroring the tuonelang program's and the C
// peer's realloc doubling, rather than Go's built-in append heuristic, so the
// three grow identically), summed; and a growable byte buffer filled to `count`
// bytes the same way, measured by length. Go's GC reclaims each round's buffers
// (the peer to tuonelang's drop-glue free and C's explicit free); the round is
// repeated so the workload really exercises heap allocation/growth throughput.
// The observable result is one round's contribution (reassigned, not
// accumulated): for count = 16 the vector sums to 120 and the buffer is 16
// bytes, so main returns 136.
package main

import "os"

func arraySum(count int) int64 {
	var xs []int64
	var length int64 = 0
	var cap64 int64 = 0
	for i := 0; i < count; i++ {
		if length == cap64 {
			if cap64 == 0 {
				cap64 = 1
			} else {
				cap64 *= 2
			}
			grown := make([]int64, cap64)
			copy(grown, xs[:length])
			xs = grown
		}
		xs[length] = int64(i)
		length++
	}
	var total int64 = 0
	for j := int64(0); j < length; j++ {
		total += xs[j]
	}
	return total
}

func stringLen(count int) int64 {
	var s []byte
	var length int64 = 0
	var cap64 int64 = 0
	for i := 0; i < count; i++ {
		if length == cap64 {
			if cap64 == 0 {
				cap64 = 1
			} else {
				cap64 *= 2
			}
			grown := make([]byte, cap64)
			copy(grown, s[:length])
			s = grown
		}
		s[length] = 65
		length++
	}
	return length
}

func roundOnce(count int) int64 {
	return arraySum(count) + stringLen(count)
}

func main() {
	var result int64 = 0
	for r := 0; r < 2000; r++ {
		result = roundOnce(16)
	}
	os.Exit(int(result))
}

// map-lookup — the equivalent-semantics C peer for the tuonelang map-lookup
// workload (ADR-0011's `Map[Int, Int]`). Same computation the same way: an
// open-addressing hash table (splitmix64-finalizer hash, linear probing,
// doubling growth) receives `count` inserts (key i → 3·i), every key is
// looked back up summing values modulo 1000, and the first half is removed
// (tombstone deletion — the idiomatic C shape; the observable results agree
// since the workload never iterates). One round contributes
// 3·999·1000/2 % 1000 + 500 = 1000 for count = 1000; the round repeats and
// the result is reassigned, not accumulated, so main returns 1000 & 0xff =
// 232.

#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int64_t *keys;
    int64_t *values;
    uint8_t *state; /* 0 empty, 1 live, 2 tombstone */
    uint64_t cap;
    uint64_t len;
} table;

static uint64_t mix(int64_t key) {
    uint64_t x = (uint64_t)key;
    x ^= x >> 30; x *= 0xbf58476d1ce4e5b9ULL;
    x ^= x >> 27; x *= 0x94d049bb133111ebULL;
    x ^= x >> 31;
    return x;
}

static void grow(table *t, uint64_t new_cap) {
    int64_t *keys = malloc(new_cap * sizeof(int64_t));
    int64_t *values = malloc(new_cap * sizeof(int64_t));
    uint8_t *state = calloc(new_cap, 1);
    for (uint64_t i = 0; i < t->cap; i++) {
        if (t->state[i] != 1) continue;
        uint64_t slot = mix(t->keys[i]) & (new_cap - 1);
        while (state[slot] == 1) slot = (slot + 1) & (new_cap - 1);
        keys[slot] = t->keys[i];
        values[slot] = t->values[i];
        state[slot] = 1;
    }
    free(t->keys);
    free(t->values);
    free(t->state);
    t->keys = keys;
    t->values = values;
    t->state = state;
    t->cap = new_cap;
}

static void insert(table *t, int64_t k, int64_t v) {
    if (t->cap == 0 || 2 * (t->len + 1) > t->cap) grow(t, t->cap ? t->cap * 2 : 16);
    uint64_t slot = mix(k) & (t->cap - 1);
    while (t->state[slot] == 1) {
        if (t->keys[slot] == k) {
            t->values[slot] = v;
            return;
        }
        slot = (slot + 1) & (t->cap - 1);
    }
    t->keys[slot] = k;
    t->values[slot] = v;
    t->state[slot] = 1;
    t->len += 1;
}

static int64_t get(const table *t, int64_t k, int64_t missing) {
    if (t->cap == 0) return missing;
    uint64_t slot = mix(k) & (t->cap - 1);
    while (t->state[slot] != 0) {
        if (t->state[slot] == 1 && t->keys[slot] == k) return t->values[slot];
        slot = (slot + 1) & (t->cap - 1);
    }
    return missing;
}

static void del(table *t, int64_t k) {
    if (t->cap == 0) return;
    uint64_t slot = mix(k) & (t->cap - 1);
    while (t->state[slot] != 0) {
        if (t->state[slot] == 1 && t->keys[slot] == k) {
            t->state[slot] = 2;
            t->len -= 1;
            return;
        }
        slot = (slot + 1) & (t->cap - 1);
    }
}

static long long round_once(long long count) {
    table t = {0, 0, 0, 0, 0};
    for (long long i = 0; i < count; i++) insert(&t, i, i * 3);
    long long hits = 0;
    for (long long j = 0; j < count; j++) hits = (hits + get(&t, j, 0)) % 1000;
    for (long long k = 0; k < count / 2; k++) del(&t, k);
    long long result = hits + (long long)t.len;
    free(t.keys);
    free(t.values);
    free(t.state);
    return result;
}

int main(void) {
    long long result = 0;
    for (int r = 0; r < 50; r++) {
        result = round_once(1000);
    }
    return (int)result; /* 1000 & 0xff = 232 via the process exit byte */
}

// map-lookup — the equivalent-semantics Go peer for the tuonelang map-lookup
// workload (ADR-0011's `Map[Int, Int]`). Same computation the same way,
// through Go's built-in map: `count` inserts (key i → 3·i), every key looked
// back up summing values modulo 1000, then the first half deleted. The
// workload never iterates the map, so Go's randomized iteration order is
// irrelevant and the observable result agrees with the tuonelang and C
// peers: one round contributes 3·999·1000/2 % 1000 + 500 = 1000 for
// count = 1000; the round repeats and the result is reassigned, not
// accumulated, so main exits 1000 & 0xff = 232.
package main

import "os"

func round(count int64) int64 {
	m := make(map[int64]int64)
	for i := int64(0); i < count; i++ {
		m[i] = i * 3
	}
	var hits int64
	for j := int64(0); j < count; j++ {
		hits = (hits + m[j]) % 1000
	}
	for k := int64(0); k < count/2; k++ {
		delete(m, k)
	}
	return hits + int64(len(m))
}

func main() {
	var result int64
	for r := 0; r < 50; r++ {
		result = round(1000)
	}
	os.Exit(int(result & 0xff))
}

