}

/* json-parse — the equivalent-semantics C peer for the tuonelang json-parse
 * workload (ADR-0016). The identical walk: per round, recursive-descent
 * parse of the same fixed document (numbers via strtod — the same decimal
 * accumulation), counting nodes and summing every number, then fold the
 * same structural checksum: (nodes * 3 + (long long)sum) % 256 = 54, the
 * exit byte (the last round's value, reassigned, not accumulated). */
#include <stdlib.h>

static const char *DOC =
    "{\"id\":42,\"name\":\"tuonelang\",\"tags\":[\"fast\",\"safe\",\"native\"],"
    "\"metrics\":{\"stars\":128,\"forks\":32,\"score\":9.5},\"active\":true,"
    "\"refs\":[1,2,3,4,5,6,7,8]}";

static const char *skip_ws(const char *p) {
    while (*p == ' ') p++;
    return p;
}

static const char *string_end(const char *p) {
    p++;
    while (*p && *p != '"') p++;
    return p + 1;
}

static const char *parse_value(const char *p, long long *nodes, double *sum);

static const char *parse_items(const char *p, char closer, long long *nodes,
                               double *sum) {
    p = skip_ws(p);
    if (*p == closer) return p + 1;
    for (;;) {
        char c;
        if (closer == '}') {
            p = skip_ws(p);
            p = string_end(p);
            p = skip_ws(p);
            p++; /* ':' */
        }
        p = parse_value(p, nodes, sum);
        p = skip_ws(p);
        c = *p;
        p++;
        if (c == closer) return p;
    }
}

static const char *parse_value(const char *p, long long *nodes, double *sum) {
    p = skip_ws(p);
    (*nodes)++;
    if (*p == 'n' || *p == 't') return p + 4;
    if (*p == 'f') return p + 5;
    if (*p == '"') return string_end(p);
    if (*p == '[') return parse_items(p + 1, ']', nodes, sum);
    if (*p == '{') return parse_items(p + 1, '}', nodes, sum);
    {
        char *end;
        *sum += strtod(p, &end);
        return end;
    }
}

static long long round_trip(void) {
    long long nodes = 0;
    double sum = 0.0;
    parse_value(DOC, &nodes, &sum);
    return (nodes * 3 + (long long)sum) % 256;
}

int main(void) {
    long long result = 0;
    long long r;
    for (r = 0; r < 200; r++) {
        result = round_trip();
    }
    return (int)(result & 0xff);
}

// json-parse — the equivalent-semantics Go peer for the tuonelang json-parse
// workload, and the parity target ADR-0016 answers: Go's standard
// `encoding/json` unmarshals the same fixed document into `any` and the walk
// folds the identical structural checksum — one node per JSON value, every
// number summed — (nodes * 3 + int64(sum)) % 256 = 54, the exit byte (the
// last round's value, reassigned, not accumulated). The walk is
// order-independent (count + sum), so Go's randomized map iteration cannot
// change the answer.
package main

import (
	"encoding/json"
	"os"
)

const doc = `{"id":42,"name":"tuonelang","tags":["fast","safe","native"],` +
	`"metrics":{"stars":128,"forks":32,"score":9.5},"active":true,` +
	`"refs":[1,2,3,4,5,6,7,8]}`

func walk(v any, nodes *int64, sum *float64) {
	*nodes++
	switch value := v.(type) {
	case map[string]any:
		for _, child := range value {
			walk(child, nodes, sum)
		}
	case []any:
		for _, child := range value {
			walk(child, nodes, sum)
		}
	case float64:
		*sum += value
	}
}

func roundTrip() int64 {
	var parsed any
	if err := json.Unmarshal([]byte(doc), &parsed); err != nil {
		return -1
	}
	var nodes int64 = 0
	var sum float64 = 0.0
	walk(parsed, &nodes, &sum)
	return (nodes*3 + int64(sum)) % 256
}

func main() {
	var result int64 = 0
	for r := int64(0); r < 200; r++ {
		result = roundTrip()
	}
	os.Exit(int(result & 0xff))
}

/* sha256-hash — the equivalent-semantics C peer for the tuonelang sha256-hash
 * workload (ADR-0019). The identical computation: the same fixed 64-byte
 * message, the same FIPS 180-4 compression function over uint32_t with the
 * same rotations, shifts, and modular additions, across the same two padded
 * blocks. 200 rounds; the exit byte is the digest's first byte (0x96 = 150),
 * the last round's value (reassigned, not accumulated). */
#include <stdint.h>
#include <string.h>

static const uint32_t K[64] = {
    0x428a2f98u, 0x71374491u, 0xb5c0fbcfu, 0xe9b5dba5u, 0x3956c25bu, 0x59f111f1u,
    0x923f82a4u, 0xab1c5ed5u, 0xd807aa98u, 0x12835b01u, 0x243185beu, 0x550c7dc3u,
    0x72be5d74u, 0x80deb1feu, 0x9bdc06a7u, 0xc19bf174u, 0xe49b69c1u, 0xefbe4786u,
    0x0fc19dc6u, 0x240ca1ccu, 0x2de92c6fu, 0x4a7484aau, 0x5cb0a9dcu, 0x76f988dau,
    0x983e5152u, 0xa831c66du, 0xb00327c8u, 0xbf597fc7u, 0xc6e00bf3u, 0xd5a79147u,
    0x06ca6351u, 0x14292967u, 0x27b70a85u, 0x2e1b2138u, 0x4d2c6dfcu, 0x53380d13u,
    0x650a7354u, 0x766a0abbu, 0x81c2c92eu, 0x92722c85u, 0xa2bfe8a1u, 0xa81a664bu,
    0xc24b8b70u, 0xc76c51a3u, 0xd192e819u, 0xd6990624u, 0xf40e3585u, 0x106aa070u,
    0x19a4c116u, 0x1e376c08u, 0x2748774cu, 0x34b0bcb5u, 0x391c0cb3u, 0x4ed8aa4au,
    0x5b9cca4fu, 0x682e6ff3u, 0x748f82eeu, 0x78a5636fu, 0x84c87814u, 0x8cc70208u,
    0x90befffau, 0xa4506cebu, 0xbef9a3f7u, 0xc67178f2u};

static uint32_t rotr32(uint32_t x, unsigned n) {
    return (x >> n) | (x << (32 - n));
}

static unsigned first_digest_byte(const unsigned char *msg, int len) {
    uint32_t h[8] = {0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
                     0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u};

    for (int base = 0; base < len; base += 64) {
        uint32_t w[64];
        for (int t = 0; t < 16; t++) {
            int at = base + t * 4;
            w[t] = ((uint32_t)msg[at] << 24) | ((uint32_t)msg[at + 1] << 16) |
                   ((uint32_t)msg[at + 2] << 8) | (uint32_t)msg[at + 3];
        }
        for (int t = 16; t < 64; t++) {
            uint32_t s0 = rotr32(w[t - 15], 7) ^ rotr32(w[t - 15], 18) ^ (w[t - 15] >> 3);
            uint32_t s1 = rotr32(w[t - 2], 17) ^ rotr32(w[t - 2], 19) ^ (w[t - 2] >> 10);
            w[t] = w[t - 16] + s0 + w[t - 7] + s1;
        }

        uint32_t a = h[0], b = h[1], c = h[2], d = h[3];
        uint32_t e = h[4], f = h[5], g = h[6], hh = h[7];
        for (int r = 0; r < 64; r++) {
            uint32_t big1 = rotr32(e, 6) ^ rotr32(e, 11) ^ rotr32(e, 25);
            uint32_t ch = (e & f) ^ ((~e) & g);
            uint32_t t1 = hh + big1 + ch + K[r] + w[r];
            uint32_t big0 = rotr32(a, 2) ^ rotr32(a, 13) ^ rotr32(a, 22);
            uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            uint32_t t2 = big0 + maj;
            hh = g; g = f; f = e; e = d + t1;
            d = c; c = b; b = a; a = t1 + t2;
        }
        h[0] += a; h[1] += b; h[2] += c; h[3] += d;
        h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
    }
    return (unsigned)((h[0] >> 24) & 255u);
}

int main(void) {
    /* The same 64-byte message, padded to two blocks: 0x80, zeros, then the
     * 64-bit big-endian bit length (512 = 0x200). */
    unsigned char msg[128];
    memset(msg, 0, sizeof msg);
    for (int i = 0; i < 64; i++) msg[i] = (unsigned char)(48 + (i % 10));
    msg[64] = 0x80;
    msg[126] = 0x02;

    unsigned first = 0;
    for (int round = 0; round < 200; round++) {
        first = first_digest_byte(msg, 128);
    }
    return (int)first;
}

// sha256-hash — the equivalent-semantics Go peer for the tuonelang sha256-hash
// workload, and the parity target ADR-0019 answers: Go's standard
// `crypto/sha256` digests the same fixed 64-byte message, and the exit byte is
// the digest's first byte (0x96 = 150), the last round's value (reassigned,
// not accumulated) over 200 rounds.
package main

import (
	"crypto/sha256"
	"os"
)

func message() []byte {
	m := make([]byte, 64)
	for i := range m {
		m[i] = byte(48 + (i % 10))
	}
	return m
}

func main() {
	m := message()
	first := 0
	for round := 0; round < 200; round++ {
		sum := sha256.Sum256(m)
		first = int(sum[0])
	}
	os.Exit(first)
}

/* wire-decode — the equivalent-semantics C peer for the tuonelang wire-decode
 * workload (ADR-0019). The identical walk: the same 256-byte buffer of 16
 * length-prefixed frames, per frame a big-endian 4-byte length and 2-byte
 * type decoded with the same shifts and masks, the length re-encoded and
 * checked byte-for-byte, and the payload folded into the same checksum.
 * 200 rounds; the exit byte is the last round's checksum (reassigned, not
 * accumulated) = 120. */
#include <stdint.h>

#define BUF_LEN 256

static void fill(unsigned char *buf) {
    int at = 0;
    for (int frame = 0; frame < 16; frame++) {
        buf[at++] = 0;
        buf[at++] = 0;
        buf[at++] = 0;
        buf[at++] = 16;
        buf[at++] = 0;
        buf[at++] = (unsigned char)(64 + frame);
        for (int i = 0; i < 10; i++) {
            buf[at++] = (unsigned char)((frame * 7 + i) & 255);
        }
    }
}

static long long decode(const unsigned char *buf) {
    long long checksum = 0;
    int pos = 0;
    while (pos + 6 <= BUF_LEN) {
        uint32_t length = ((uint32_t)buf[pos] << 24) | ((uint32_t)buf[pos + 1] << 16) |
                          ((uint32_t)buf[pos + 2] << 8) | (uint32_t)buf[pos + 3];
        uint32_t kind = ((uint32_t)buf[pos + 4] << 8) | (uint32_t)buf[pos + 5];

        /* The round-trip: re-encoding the length must reproduce the bytes. */
        long long rebuilt = 0;
        for (int j = 0; j < 4; j++) {
            if ((int)((length >> ((3 - j) * 8)) & 255) == buf[pos + j]) rebuilt++;
        }
        checksum = (checksum + rebuilt) & 255;

        checksum = (checksum + (long long)(length & 255) + (long long)(kind & 255)) & 255;
        for (int p = pos + 6; p < pos + (int)length && p < BUF_LEN; p++) {
            checksum = (checksum ^ buf[p]) & 255;
        }
        if (length == 0) return checksum;
        pos += (int)length;
    }
    return checksum;
}

int main(void) {
    unsigned char buf[BUF_LEN];
    fill(buf);
    long long checksum = 0;
    for (int round = 0; round < 200; round++) {
        checksum = decode(buf);
    }
    return (int)checksum;
}

// wire-decode — the equivalent-semantics Go peer for the tuonelang wire-decode
// workload, and the parity target ADR-0019 answers: Go's standard
// `encoding/binary` decodes and re-encodes the same big-endian fields with
// BigEndian.Uint32/PutUint32 over the same 256-byte buffer of 16
// length-prefixed frames, folding the identical checksum = 120, the exit byte
// (the last round's value, reassigned, not accumulated).
package main

import (
	"encoding/binary"
	"os"
)

const bufLen = 256

func fill() []byte {
	buf := make([]byte, 0, bufLen)
	for frame := 0; frame < 16; frame++ {
		buf = append(buf, 0, 0, 0, 16, 0, byte(64+frame))
		for i := 0; i < 10; i++ {
			buf = append(buf, byte((frame*7+i)&255))
		}
	}
	return buf
}

func decode(buf []byte) int {
	checksum := 0
	pos := 0
	var scratch [4]byte
	for pos+6 <= bufLen {
		length := binary.BigEndian.Uint32(buf[pos : pos+4])
		kind := binary.BigEndian.Uint16(buf[pos+4 : pos+6])

		// The round-trip: re-encoding the length must reproduce the bytes.
		binary.BigEndian.PutUint32(scratch[:], length)
		rebuilt := 0
		for j := 0; j < 4; j++ {
			if scratch[j] == buf[pos+j] {
				rebuilt++
			}
		}
		checksum = (checksum + rebuilt) & 255

		checksum = (checksum + int(length&255) + int(kind&255)) & 255
		for p := pos + 6; p < pos+int(length) && p < bufLen; p++ {
			checksum = (checksum ^ int(buf[p])) & 255
		}
		if length == 0 {
			return checksum
		}
		pos += int(length)
	}
	return checksum
}

func main() {
	buf := fill()
	checksum := 0
	for round := 0; round < 200; round++ {
		checksum = decode(buf)
	}
	os.Exit(checksum)
}

/* The udp-echo workload's C peer (ADR-0017): the identical sequence the
   tuonelang program performs — per round, bind two ephemeral loopback UDP
   sockets, then for each of 8 datagrams send 16 bytes, recvfrom them on the
   server, read all 16 bytes back out of the staging buffer, echo a reply to
   the sender's port, and receive it on the client. Equivalent semantics:
   same syscalls, same counts, same exit byte (128). */
#include <arpa/inet.h>
#include <netinet/in.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

static int bind_ephemeral(void) {
    struct sockaddr_in addr;
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) return -1;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = 0;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) != 0) {
        close(fd);
        return -1;
    }
    return fd;
}

static int port_of(int fd) {
    struct sockaddr_in addr;
    socklen_t alen = sizeof(addr);
    if (getsockname(fd, (struct sockaddr *)&addr, &alen) != 0) return -1;
    return (int)ntohs(addr.sin_port);
}

static int round_once(int datagrams) {
    struct sockaddr_in to;
    unsigned char buf[2048];
    int count = 0, i;
    int server = bind_ephemeral();
    int sport, client;
    if (server < 0) return -1;
    sport = port_of(server);
    if (sport <= 0) return -2;
    client = bind_ephemeral();
    if (client < 0) return -3;
    memset(&to, 0, sizeof(to));
    to.sin_family = AF_INET;
    to.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    for (i = 0; i < datagrams; i++) {
        struct sockaddr_in from;
        socklen_t flen = sizeof(from);
        ssize_t n;
        int b;
        to.sin_port = htons((unsigned short)sport);
        if (sendto(client, "0123456789abcdef", 16, 0,
                   (struct sockaddr *)&to, sizeof(to)) != 16)
            return -4;
        n = recvfrom(server, buf, sizeof(buf), 0,
                     (struct sockaddr *)&from, &flen);
        if (n != 16) return -5;
        /* Read every byte back out of the buffer, mirroring the
           tuonelang program's udp_byte_at loop. */
        for (b = 0; b < 16; b++) {
            if (buf[b] == 0) return -6;
            count++;
        }
        if (sendto(server, "ok", 2, 0, (struct sockaddr *)&from,
                   sizeof(from)) != 2)
            return -8;
        n = recvfrom(client, buf, sizeof(buf), 0, 0, 0);
        if (n != 2) return -9;
    }
    close(client);
    close(server);
    return count;
}

int main(void) {
    int result = 0, r;
    for (r = 0; r < 100; r++) result = round_once(8);
    return result & 0xff;
}

// The udp-echo workload's Go peer (ADR-0017): the identical sequence the
// tuonelang program performs, using Go's own net.ListenPacket /
// WriteTo / ReadFrom — the parity target for datagram I/O. Per round, bind
// two ephemeral loopback UDP sockets, then for each of 8 datagrams send 16
// bytes, read them back on the server, echo a reply to the sender's address,
// and receive it on the client. Same counts, same exit byte (128).
package main

import (
	"net"
	"os"
)

func bindEphemeral() (net.PacketConn, error) {
	return net.ListenPacket("udp4", "127.0.0.1:0")
}

func roundOnce(datagrams int) int {
	server, err := bindEphemeral()
	if err != nil {
		return -1
	}
	defer server.Close()
	client, err := bindEphemeral()
	if err != nil {
		return -3
	}
	defer client.Close()

	payload := []byte("0123456789abcdef")
	buf := make([]byte, 2048)
	count := 0
	for i := 0; i < datagrams; i++ {
		if n, err := client.WriteTo(payload, server.LocalAddr()); err != nil || n != 16 {
			return -4
		}
		n, from, err := server.ReadFrom(buf)
		if err != nil || n != 16 {
			return -5
		}
		for b := 0; b < 16; b++ {
			if buf[b] == 0 {
				return -6
			}
			count++
		}
		if n, err := server.WriteTo([]byte("ok"), from); err != nil || n != 2 {
			return -8
		}
		if n, _, err := client.ReadFrom(buf); err != nil || n != 2 {
			return -9
		}
	}
	return count
}

func main() {
	result := 0
	for r := 0; r < 100; r++ {
		result = roundOnce(8)
	}
	os.Exit(result & 0xff)
}

/* The connect-timeout workload's C peer (ADR-0017): the identical sequence
   the tuonelang program performs, using the standard bounded-connect idiom —
   non-blocking connect + poll(POLLOUT) with the same deadline, consulting
   SO_ERROR. Same round count, same bounded-outcome accounting, same exit
   byte (200). */
#include <errno.h>
#include <fcntl.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <poll.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

static int dead_port(void) {
    struct sockaddr_in addr;
    socklen_t alen = sizeof(addr);
    int port, fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return -1;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = 0;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) != 0 ||
        listen(fd, 16) != 0 ||
        getsockname(fd, (struct sockaddr *)&addr, &alen) != 0) {
        close(fd);
        return -1;
    }
    port = (int)ntohs(addr.sin_port);
    close(fd);
    return port;
}

/* Returns 1 when the attempt came back bounded (refused or timed out). */
static int round_once(int port, int ms) {
    struct sockaddr_in addr;
    struct pollfd pfd;
    int fd, flags, err = 0;
    socklen_t errlen = sizeof(err);
    fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return 0;
    flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) < 0) {
        close(fd);
        return 0;
    }
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons((unsigned short)port);
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) == 0) {
        close(fd); /* someone accepted: not the bounded-failure path */
        return 0;
    }
    if (errno != EINPROGRESS) {
        close(fd); /* refused immediately — a bounded outcome */
        return 1;
    }
    pfd.fd = fd;
    pfd.events = POLLOUT;
    pfd.revents = 0;
    if (poll(&pfd, 1, ms) == 0) {
        close(fd); /* timed out — a bounded outcome */
        return 1;
    }
    if (getsockopt(fd, SOL_SOCKET, SO_ERROR, &err, &errlen) != 0 || err != 0) {
        close(fd);
        return 1;
    }
    close(fd);
    return 0;
}

int main(void) {
    int port = dead_port(), count = 0, r;
    if (port <= 0) return 1;
    for (r = 0; r < 200; r++) count += round_once(port, 50);
    return count & 0xff;
}

// The connect-timeout workload's Go peer (ADR-0017): the identical sequence
// the tuonelang program performs, using Go's own net.DialTimeout — the
// parity target for a bounded connect. Same round count, same
// bounded-outcome accounting, same exit byte (200).
package main

import (
	"net"
	"os"
	"strconv"
	"time"
)

func deadPort() int {
	l, err := net.Listen("tcp4", "127.0.0.1:0")
	if err != nil {
		return -1
	}
	port := l.Addr().(*net.TCPAddr).Port
	l.Close()
	return port
}

// Returns 1 when the attempt came back bounded (refused or timed out).
func roundOnce(port int, d time.Duration) int {
	addr := net.JoinHostPort("127.0.0.1", strconv.Itoa(port))
	conn, err := net.DialTimeout("tcp4", addr, d)
	if err != nil {
		return 1
	}
	conn.Close()
	return 0
}

func main() {
	port := deadPort()
	if port <= 0 {
		os.Exit(1)
	}
	count := 0
	for r := 0; r < 200; r++ {
		count += roundOnce(port, 50*time.Millisecond)
	}
	os.Exit(count & 0xff)
}
